tests.code:
long a[] = {9, 4, 7, 1, 8, 2};
heapify(a, 6);
/* min-heap property: parent <= children */
CHECK(a[0] == 1);                        /* min at root */
for (size_t i = 1; i < 6; i++) {
    size_t p = (i - 1) / 2;
    CHECK(a[p] <= a[i]);
}
long b[] = {5, 3, 8, 1, 9, 2, 7};
heapsort_asc(b, 7);
for (int i = 0; i < 6; i++) CHECK(b[i] <= b[i + 1]);
CHECK(b[0] == 1 && b[6] == 9);
long one[] = {42};
heapify(one, 1);
CHECK(one[0] == 42);
heapsort_asc(one, 1);
CHECK(one[0] == 42);
